text:
Errors
Polars errors are thrown as subclasses of Phpolars\PolarsError, named after the py-polars exceptions: ColumnNotFoundError, ComputeError, DuplicateError, InvalidOperationError, NoDataError, OutOfBoundsError, SchemaError, SchemaFieldNotFoundError, ShapeError, and StructFieldNotFoundError, all in Phpolars\Exception. Invalid arguments raise PHP’s ValueError.
use Phpolars\Exception\{ColumnNotFoundError, SchemaError};

$df = new DataFrame(['a' =&gt; [1, 2]]);

try {
    $df-&gt;select('b');
} catch (ColumnNotFoundError $e) {
    echo get_class($e), ': ', strtok($e-&gt;getMessage(), "\n"), "\n";
}
try {
    new DataFrame(['a' =&gt; [1, 'two']]);
} catch (SchemaError $e) {
    echo get_class($e), ': ', $e-&gt;getMessage(), "\n";
}
echo $e instanceof Phpolars\PolarsError ? "both extend Phpolars\\PolarsError\n" : '';
Phpolars\Exception\ColumnNotFoundError: not found: unable to find column "b"; valid columns: ["a"]
Phpolars\Exception\SchemaError: column 'a' mixes incompatible types; pass a dtype or cast first
both extend Phpolars\PolarsError

Dates and times
$data = 'https://raw.githubusercontent.com'
    .'/phpstats/datasets/main/csv';
$weather = read_csv(
    "$data/weather.csv",
    columns: ['time_hour'],
    tryParseDates: true,
)-&gt;head(3);

$t = col('time_hour');
echo $weather-&gt;withColumns(
    $t-&gt;dt()-&gt;weekday()-&gt;alias('weekday'),
    $t-&gt;dt()-&gt;hour()-&gt;alias('hour'),
    $t-&gt;dt()-&gt;convertTimeZone('America/New_York')
        -&gt;dt()-&gt;strftime('%b %d %H:%M')-&gt;alias('new_york'),
    $t-&gt;dt()-&gt;truncate('1d')-&gt;alias('day'),
), "\n";

// Date and Datetime values come back as DateTimeImmutable.
$first = $weather-&gt;item(0, 'time_hour');
echo get_class($first), ' ', $first-&gt;format('c'), "\n";
