PolarsTable pipeline

PHP 8.5+PHP 8.3–8.4


use Phibble\Polars\PolarsTable;
use function Phplyr\{col, filter, group_by, mean, n, summarize};

$table = PolarsTable::fromPolars(Phpolars\read_csv('penguins.csv', nullValues: 'NA'));

$out = $table |&gt;
    group_by('species') |&gt;
    filter(col('body_mass_g')-&gt;gt(mean('body_mass_g', naRm: true))) |&gt;
    summarize(penguins: n(), mass_g: mean('body_mass_g'));


use Phibble\Polars\PolarsTable;
use function Phplyr\{col, mean, n, phplyr};

$table = PolarsTable::fromPolars(Phpolars\read_csv('penguins.csv', nullValues: 'NA'));

$out = phplyr($table)
    -&gt;groupBy('species')
    -&gt;filter(col('body_mass_g')-&gt;gt(mean('body_mass_g', naRm: true)))
    -&gt;summarize(penguins: n(), mass_g: mean('body_mass_g'))
    -&gt;get();



$out is a PolarsTable. $out-&gt;collect() copies it into a Phibble\DataFrame:
